<?php
declare(strict_types=1);require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/catalog-store.php';header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');$admin=!empty($is_member)&&($is_admin??'')==='super';$entities=[];$batch=null;$tracks=[];$detail=null;$selected=(string)($_GET['id']??'');if($selected!==''&&!preg_match('/^[a-f0-9]{64}$/D',$selected)){http_response_code(400);exit;}
try{$db=noa_bridge_pdo();if(nc_exists($db,'noa_catalog_batches')){$batch=$db->query("SELECT batch_id FROM noa_catalog_batches WHERE status='applied' ORDER BY applied_at DESC,batch_id DESC LIMIT 1")->fetchColumn();if($batch){$q=$db->prepare("SELECT v.*,s.genre_id,s.ep,s.language,s.version_name,p.owner_id,a.genre_id AS act_genre,a.act_number FROM noa_catalog_versions v LEFT JOIN noa_catalog_songs s ON v.entity_id=s.song_id LEFT JOIN noa_catalog_playlists p ON v.entity_id=p.playlist_id LEFT JOIN noa_catalog_acts a ON p.act_id=a.act_id WHERE v.batch_id=? ORDER BY v.entity_type,s.genre_id,CAST(s.ep AS UNSIGNED),v.entity_id");$q->execute([$batch]);foreach($q as $row){$private=$row['owner_id']!==null;$own=$private&&!empty($is_member)&&$row['owner_id']===($member['mb_id']??'');if($private&&!$admin&&!$own||!$admin&&!$own&&!$row['public_verified'])continue;$row['fields']=json_decode($row['fields_json'],true,512,JSON_THROW_ON_ERROR);$row['review']=json_decode($row['review_fields'],true);$entities[$row['entity_id']]=$row;}if($selected!==''&&isset($entities[$selected])){$detail=$entities[$selected];$q=$db->prepare('SELECT t.*,v.fields_json FROM noa_catalog_tracks t LEFT JOIN noa_catalog_versions v ON t.batch_id=v.batch_id AND t.song_id=v.entity_id WHERE t.batch_id=? AND t.playlist_id=? ORDER BY t.variant_id,t.position');$q->execute([$batch,$selected]);$tracks=$q->fetchAll(PDO::FETCH_ASSOC);}elseif($selected!==''){http_response_code(404);exit('이 곡은 공개되어 있지 않거나 찾을 수 없습니다.');}}}}catch(Throwable $e){error_log('[noa-catalog-public] '.get_class($e));http_response_code(503);exit('통합 음악 정보를 읽지 못했습니다.');}
function nche(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function nc_link(mixed $value,string $label):string{if(!is_string($value)||!preg_match('~^https://~',$value))return '';return '<a href="'.nche($value).'" target="_blank" rel="noopener noreferrer">'.nche($label).' ↗</a>';}
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>통합 음악 라이브러리 | NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css"><link rel="stylesheet" href="/noa-ai-lab.css"><script src="/noa-ui.js" defer></script><style>.catalog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px}.catalog-card{padding:22px;border:1px solid var(--noa-line);border-radius:12px;text-decoration:none;background:var(--noa-surface)}.catalog-card strong{display:block;margin:8px 0}.catalog-card small{color:var(--noa-muted)}.catalog-links{display:flex;gap:18px;flex-wrap:wrap}.catalog-lyrics{white-space:pre-wrap;overflow-wrap:anywhere}.catalog-track{padding:14px 0;border-bottom:1px solid var(--noa-line)}.catalog-meta{color:var(--noa-muted);font-size:13px}</style></head><body class="noa-page"><main><p class="noa-eyebrow">NOA STUDIO / ONE MUSIC LIBRARY</p><h1>통합 음악 라이브러리</h1><div class="catalog-links"><a href="/noa-music.php">음악 감상</a><a href="/noa-catalog.php">통합 목록</a><?php if($admin):?><a href="/noa-catalog-admin.php">SQL 통합·충돌 검토</a><?php endif;?></div><?php if(!$batch):?><p>통합 음악 데이터를 준비하고 있습니다.</p><?php elseif($detail):$f=$detail['fields'];?><section class="lab-panel"><p class="noa-eyebrow"><?=nche(($detail['genre_id']??$detail['act_genre']??'').' · '.($detail['ep']?'EP.'.$detail['ep']:($detail['act_number']?'ACT.'.$detail['act_number']:($detail['entity_type']==='song'?'SONG':'PLAYLIST'))))?></p><h2><?=nche($f['title']??'제목 검토 중')?></h2><?php if($detail['review']):?><p class="catalog-meta">관리자 검토 중인 필드: <?=nche(implode(', ',$detail['review']))?></p><?php endif;?><div class="catalog-links"><?=nc_link($f['sunoShareUrl']??$f['sunoUrl']??null,'Suno')?><?=nc_link($f['youtubeUrl']??null,'YouTube')?><?=nc_link($f['mvUrl']??null,'MV')?></div><?php if(!empty($f['thumbUrl'])&&preg_match('~^https://~',$f['thumbUrl'])):?><img src="<?=nche($f['thumbUrl'])?>" alt="곡 썸네일" loading="lazy" style="max-width:640px;width:100%;margin:24px 0"><?php endif;?><?php if(isset($f['lyricsBlock'])):?><h3>가사</h3><div class="catalog-lyrics"><?=nche($f['lyricsBlock'])?></div><?php endif;?><?php if($tracks):?><h3>수록곡 · 원본 재생 순서</h3><?php $variant='';foreach($tracks as $t):$tf=json_decode($t['fields_json']??'{}',true);$raw=json_decode($t['raw_json'],true);if($variant!==$t['variant_id']){$variant=$t['variant_id'];echo '<p class="catalog-meta">목록 버전 '.nche(substr($variant,0,12)).'</p>';}?><div class="catalog-track"><strong><?=$t['position']?>.</strong> <?php if(isset($entities[$t['song_id']??''])):?><a href="?id=<?=nche($t['song_id'])?>"><?=nche($tf['title']??$raw['title']??'제목 검토 중')?></a><?php else:?><?=nche($raw['title']??$raw['raw']??'곡 식별 검토 중')?><?php endif;?> <small class="catalog-meta"><?=nche(['verified'=>'순서 확인','order_review'=>'순서 검토','unresolved'=>'곡 식별 검토'][$t['status']]??$t['status'])?></small></div><?php endforeach;endif;?></section><?php else:?><p class="noa-muted"><?=$admin?'관리자 전체 통합 문서':'기존에 공개가 확인된 음악·ACT 및 내 플레이리스트'?> <?=count($entities)?>개</p><label>제목·장르·EP 검색 <input id="catalog-search" type="search" placeholder="듣고 싶은 곡을 찾아보세요"></label><h2>곡·ACT·플레이리스트</h2><div class="catalog-grid"><?php foreach($entities as $id=>$e):$f=$e['fields'];$meta=($e['genre_id']??$e['act_genre']??'').' · '.($e['ep']?'EP.'.$e['ep']:($e['act_number']?'ACT.'.$e['act_number']:($e['entity_type']==='song'?'SONG':'PLAYLIST')));?><a class="catalog-card" href="?id=<?=nche($id)?>" data-search="<?=nche(mb_strtolower(($f['title']??'').' '.$meta))?>"><small><?=nche($meta)?></small><strong><?=nche($f['title']??'제목 검토 중')?></strong><small><?=nche(($e['language']??'').' '.(($e['version_name']??'')==='unspecified'?'버전 미지정':($e['version_name']??'')))?><?=$e['review']?' · 필드 검토 중':''?></small></a><?php endforeach;?></div><script>document.getElementById('catalog-search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q));};</script><?php endif;?></main></body></html>
